-- Stacko_Instagram_Plan_Review.xlsx: 20 library entries (scripts/import/image-batch.py). Idempotent.
do $$
declare v_brand uuid := (select id from public.brands where name = 'Stacko' order by created_at limit 1);
begin
  if v_brand is null then raise exception 'brand not found'; end if;
  insert into public.library_items (brand_id, code, kind, status, title, collection, aspect, prompt, use_for,
    when_to_use, fits_posts, notes, placeholders)
  select v_brand, i.code, i.kind, i.status, left(i.title, 300), i.collection, i.aspect, i.prompt, i.use_for,
    i.when_to_use, i.fits_posts, i.notes, i.placeholders
  from jsonb_to_recordset($lib$[{"code": "OB-33", "kind": "post_image", "status": "approved", "title": "A see-through \"ghost\" box among real cardboard boxes", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A neat row of cardboard boxes on a glossy dark floor; one box in the middle is a transparent, ghost-like glass box with a faint teal edge glow, empty inside, as if it only exists on paper. Composition: row across the lower half, ghost box centred; top 40% empty. Style: photoreal 3D product render, seamless dark navy studio, glossy dark floor with soft reflections, sharp focus. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Phantom stock: the system says it exists, the shelf says no", "when_to_use": null, "fits_posts": "IDEA-148, IDEA-149; IDEA-148, IDEA-149", "notes": "Theme: Dark", "placeholders": null}, {"code": "OB-34", "kind": "post_image", "status": "approved", "title": "One box covered in dust and cobwebs among fresh boxes", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A high warehouse shelf seen at eye level: fresh clean cardboard boxes on both sides, and in the middle one old box covered in thick grey dust and fine cobwebs, a cool spotlight on it. Composition: shelf across the lower-middle; top 40% dark and calm. Style: photoreal, cinematic, macro detail on the dust. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Dead stock, slow movers, cash gathering dust", "when_to_use": null, "fits_posts": "IDEA-150; IDEA-150", "notes": "Theme: Dark", "placeholders": null}, {"code": "OB-35", "kind": "post_image", "status": "approved", "title": "A box tipping over, spilling silver coins", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A cardboard box tipped on its side on a glossy dark floor, a stream of silver coins spilling out and spreading across the floor, soft teal rim light. Composition: box on the left, coins flowing to the right in the lower half; top 40% empty. Style: photoreal 3D product render, seamless dark navy studio, glossy dark floor with soft reflections, sharp focus. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Cash tied up in stock, cost of inaction", "when_to_use": null, "fits_posts": "IDEA-152; IDEA-152", "notes": "Theme: Dark", "placeholders": null}, {"code": "OB-36", "kind": "post_image", "status": "approved", "title": "Boxes jammed in the neck of a giant glass bottle", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A giant clear glass bottle lying on its side on a pale studio floor; many small cardboard boxes are packed inside the body, and several are jammed in the narrow neck, unable to get out. Composition: bottle across the lower 60%, neck pointing right; top 35% clean. Style: photoreal 3D product render, seamless pale blue-white studio (#F4F8FA), soft daylight, gentle shadows. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Bottlenecks: receiving, manual entry, approvals", "when_to_use": null, "fits_posts": "IDEA-157; IDEA-157", "notes": "Theme: Light", "placeholders": null}, {"code": "OB-37", "kind": "post_image", "status": "approved", "title": "Sleek calculator with a blank display resting on a box", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A sleek white desktop calculator with a completely blank display (no digits) resting on top of a closed cardboard box, pale studio, soft teal reflection on the display glass. Composition: object centred in the lower 55%; top 40% clean. Style: photoreal 3D product render, seamless pale blue-white studio (#F4F8FA), soft daylight, gentle shadows. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "\"Calculate it yourself\" cost posts, lead magnets", "when_to_use": null, "fits_posts": "IDEA-151; IDEA-151", "notes": "Theme: Light", "placeholders": null}, {"code": "OB-38", "kind": "post_image", "status": "approved", "title": "Silver key with a teal ribbon on a closed box", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A single elegant silver key with a thin teal ribbon tied to it, resting on top of a closed cardboard box on a glossy dark surface, soft spotlight. Composition: box and key centred in the lower half; top 40% empty. Style: photoreal 3D product render, seamless dark navy studio, glossy dark floor with soft reflections, sharp focus. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Founding-partner / pilot invitation, \"first keys\"", "when_to_use": null, "fits_posts": "IDEA-168; IDEA-168", "notes": "Theme: Dark", "placeholders": null}, {"code": "OB-39", "kind": "post_image", "status": "approved", "title": "Tower of boxes held up by one matchstick", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A tall, carefully balanced tower of cardboard boxes standing on a pale studio floor, held up at the base by a single thin wooden matchstick wedged under one corner. Composition: tower slightly left of centre rising to 70% height; empty space on the right. Style: photoreal 3D product render, seamless pale blue-white studio (#F4F8FA), soft daylight, gentle shadows. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Key-person risk: \"everything depends on one person\"", "when_to_use": null, "fits_posts": "IDEA-153; IDEA-153", "notes": "Theme: Light", "placeholders": null}, {"code": "OB-40", "kind": "post_image", "status": "approved", "title": "Blank calendar pages flying past a container ship model", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A small detailed container ship model on a glossy dark surface, with blank white desk-calendar pages (no numbers) flying past it as if blown by wind, soft teal light from the side. Composition: ship in the lower-right third, pages swirling through the middle; top-left calm. Style: photoreal 3D product render, seamless dark navy studio, glossy dark floor with soft reflections, sharp focus. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Lead times, deadlines, Chinese New Year + Ramadan planning", "when_to_use": null, "fits_posts": "IDEA-163, IDEA-173, IDEA-183; IDEA-163, IDEA-173, IDEA-183", "notes": "Theme: Dark", "placeholders": null}, {"code": "SC-09", "kind": "post_image", "status": "approved", "title": "Trade fair hall aisle with product booths, buyer holding a phone", "collection": "Scene", "aspect": "4:5 vertical", "prompt": "A busy international trade fair hall: a long aisle of product booths with shelves of electronics and household goods, softly blurred visitors; in the foreground a buyer's hand holds a smartphone toward the camera. Composition: phone in the lower-right, aisle receding in the centre; top 30% blurred hall ceiling. Style: photoreal editorial photography, 35mm, shallow depth of field, natural cool light. Screens: any phone, tablet or laptop screen is blank, evenly lit white, facing the camera. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Back from the Canton Fair with new SKUs", "when_to_use": null, "fits_posts": "IDEA-174; IDEA-174", "notes": "Theme: Light", "placeholders": "Blank white phone/tablet screen → place a real Stacko screen (assets/screens/)"}, {"code": "SC-10", "kind": "post_image", "status": "approved", "title": "Chinese factory loading dock at dusk, shutters down, pallets waiting", "collection": "Scene", "aspect": "4:5 vertical", "prompt": "An industrial factory loading dock at blue dusk with all rolling shutters closed, a few wrapped pallets waiting outside, an empty forklift parked, quiet atmosphere, no people, no signs. Composition: dock across the lower 55%; top 40% evening sky. Style: photoreal, wide angle, cinematic dusk. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Chinese New Year factory closures, Golden Week", "when_to_use": null, "fits_posts": "IDEA-172, IDEA-176; IDEA-172, IDEA-176", "notes": "Theme: Dark", "placeholders": null}, {"code": "SC-11", "kind": "post_image", "status": "approved", "title": "Port office desk with stacks of import papers and a stamp", "collection": "Scene", "aspect": "4:5 vertical", "prompt": "A desk in a port office: tall stacks of paper forms with only grey blank lines (nothing readable), a rubber stamp, a pen, a closed laptop; through the window, blurred cranes and containers. Composition: papers in the lower-left half; window light upper right; top-left calm. Style: photoreal editorial photography, 35mm, shallow depth of field, natural cool light. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Customs paperwork, invoices, import pain", "when_to_use": null, "fits_posts": "IDEA-180, IDEA-181; IDEA-180, IDEA-181", "notes": "Theme: Light", "placeholders": null}, {"code": "SC-12", "kind": "post_image", "status": "approved", "title": "Purchasing buyer at a desk with product samples and a laptop", "collection": "Scene", "aspect": "4:5 vertical", "prompt": "A Lebanese purchasing manager, woman in her early 30s, dark hair tied back, navy blazer, sitting at a desk covered with small product samples (cables, lamps, small boxes), looking tired at a laptop whose screen faces the camera. Composition: woman in the right half; left 40% calm office background. Style: photoreal editorial photography, 35mm, shallow depth of field, natural cool light. Screens: any phone, tablet or laptop screen is blank, evenly lit white, facing the camera. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Persona: the buyer typing supplier invoices", "when_to_use": null, "fits_posts": "IDEA-154; IDEA-154", "notes": "Theme: Light", "placeholders": "Blank white phone/tablet screen → place a real Stacko screen (assets/screens/)"}, {"code": "SC-13", "kind": "post_image", "status": "approved", "title": "Female warehouse manager with a tablet in an aisle", "collection": "Scene", "aspect": "4:5 vertical", "prompt": "A Lebanese warehouse manager, woman in her late 30s, short dark hair, navy work jacket, standing in a bright warehouse aisle holding a tablet whose screen faces the camera, a phone pressed to her ear. Composition: woman centre-right, waist up; left 40% blurred aisle. Style: photoreal editorial photography, 35mm, shallow depth of field, natural cool light. Screens: any phone, tablet or laptop screen is blank, evenly lit white, facing the camera. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Persona: the manager who gets every phone call", "when_to_use": null, "fits_posts": "IDEA-155; IDEA-155", "notes": "Theme: Light", "placeholders": "Blank white phone/tablet screen → place a real Stacko screen (assets/screens/)"}, {"code": "SC-14", "kind": "post_image", "status": "approved", "title": "Old green ledger notebook on a shop counter with receipts", "collection": "Scene", "aspect": "4:5 vertical", "prompt": "An old hardcover ledger notebook with a worn dark green cover, open on a wooden shop counter, pages with faint handwritten-looking grey lines (nothing readable), a ballpoint pen and a small pile of paper receipts beside it, soft daylight from a shop window. Composition: ledger in the lower half; top 40% soft blurred shop. Style: photoreal editorial photography, 35mm, shallow depth of field, natural cool light. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Cultural: the merchant's daftar, tradition vs growth", "when_to_use": null, "fits_posts": "IDEA-156; IDEA-156", "notes": "Theme: Light", "placeholders": null}, {"code": "SC-15", "kind": "post_image", "status": "approved", "title": "Founder's desk at night: whiteboard map sketches, laptop, sticky notes", "collection": "Scene", "aspect": "4:5 vertical", "prompt": "A small studio office at night: a whiteboard covered with hand-drawn sketches of boxes, warehouse shapes and route arrows (no words), sticky notes, a laptop with its screen facing the camera, a desk lamp. Composition: whiteboard in the upper-right, laptop lower-left; top-left calm. Style: photoreal editorial photography, 35mm, shallow depth of field, natural cool light. Screens: any phone, tablet or laptop screen is blank, evenly lit white, facing the camera. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Building in public, \"what we're building next\"", "when_to_use": null, "fits_posts": "IDEA-165, IDEA-166; IDEA-165, IDEA-166", "notes": "Theme: Dark", "placeholders": "Blank white phone/tablet screen → place a real Stacko screen (assets/screens/)"}, {"code": "SC-16", "kind": "post_image", "status": "approved", "title": "Messy stockroom with deliberate problems to spot", "collection": "Scene", "aspect": "4:5 vertical", "prompt": "A small stockroom with deliberate problems: a box blocking the aisle, mixed items on one shelf, a tipped-over box, an empty shelf slot next to an overflowing one, a ladder leaning unsafely, all clearly visible, bright even light. Composition: straight-on wide view; top 25% ceiling. Style: photoreal editorial photography, 35mm, shallow depth of field, natural cool light. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "\"Spot 3 problems\" engagement game", "when_to_use": null, "fits_posts": "IDEA-179; IDEA-179", "notes": "Theme: Light", "placeholders": null}, {"code": "UI-01", "kind": "post_image", "status": "approved", "title": "Hand holding a phone straight-on against a plain navy backdrop", "collection": "Device frame", "aspect": "4:5 vertical", "prompt": "A hand holding a modern smartphone upright and straight to the camera against a plain seamless navy backdrop, the screen perfectly flat and facing the camera, subtle teal rim light on the phone edges. Composition: phone centred, filling 65% of the height; top 15% empty. Style: photoreal product photography, straight-on, sharp. Screens: any phone, tablet or laptop screen is blank, evenly lit white, facing the camera. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Workhorse frame for real app screenshots and screen recordings", "when_to_use": null, "fits_posts": "IDEA-141, IDEA-143, IDEA-147, IDEA-160, IDEA-185; IDEA-141, IDEA-143, IDEA-147, IDEA-160, IDEA-185", "notes": "Theme: Dark", "placeholders": "Blank white phone/tablet screen → place a real Stacko screen (assets/screens/)"}, {"code": "UI-02", "kind": "post_image", "status": "approved", "title": "Laptop straight-on on a clean light desk", "collection": "Device frame", "aspect": "4:5 vertical", "prompt": "A modern laptop open on a clean pale desk, shot perfectly straight-on so the screen is a flat rectangle facing the camera, a small plant and a notebook at the sides, soft daylight. Composition: laptop centred in the lower 70%; top 25% clean wall. Style: photoreal product photography, straight-on, sharp. Screens: any phone, tablet or laptop screen is blank, evenly lit white, facing the camera. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Workhorse frame for the live map and dashboard screenshots", "when_to_use": null, "fits_posts": "IDEA-187; IDEA-187", "notes": "Theme: Light", "placeholders": "Blank white phone/tablet screen → place a real Stacko screen (assets/screens/)"}, {"code": "UI-03", "kind": "post_image", "status": "approved", "title": "Tablet top-down on a light desk with hands at the edges", "collection": "Device frame", "aspect": "4:5 vertical", "prompt": "Top-down view of a tablet lying flat on a pale wooden desk, two hands resting on its edges, screen perfectly flat and facing up, a coffee cup and a pen beside it. Composition: tablet centred, filling 60% of the frame; top 20% clear desk. Style: photoreal flat lay, soft daylight. Screens: any phone, tablet or laptop screen is blank, evenly lit white, facing the camera. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Workhorse frame for Arabic UI and map screenshots", "when_to_use": null, "fits_posts": "IDEA-146; IDEA-146", "notes": "Theme: Light", "placeholders": "Blank white phone/tablet screen → place a real Stacko screen (assets/screens/)"}, {"code": "PR-01", "kind": "post_image", "status": "approved", "title": "AI presenter in a warehouse aisle, looking at camera (9:16)", "collection": "Presenter", "aspect": "9:16 vertical", "prompt": "A friendly Lebanese presenter, woman in her early 30s, shoulder-length dark hair, navy blazer over a light-blue top, standing in a bright warehouse aisle, looking straight at the camera, mid-sentence, natural smile. Composition: 9:16 vertical, presenter centred from the waist up; top 15% and bottom 25% calm for captions. Style: photoreal editorial photography, 35mm, shallow depth of field, natural cool light. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE glow only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Host for reels: intros, FAQs, feature-in-15-seconds", "when_to_use": null, "fits_posts": "IDEA-142; IDEA-142", "notes": "Theme: Light", "placeholders": null}]$lib$::jsonb) as i(code text, kind text, status text, title text,
    collection text, aspect text, prompt text, use_for text, when_to_use text, fits_posts text, notes text,
    placeholders text)
  on conflict (brand_id, code) do nothing;
end $$;
